const MAX_SCORE = 20;
const STORAGE_KEY = "workshop-cv-v9";
const INSTRUCTOR_PIN = "1234";
const AI_TIMEOUT_MS = 25000;

// ── 스토리지 (자체 백엔드 /api/teams 사용, api/teams.js 참고) ──────
async function loadAllTeams() {
  try {
    const tp = new Promise((_, r) => setTimeout(() => r(new Error("timeout")), 4000));
    const res = await Promise.race([fetch(`/api/teams?key=${STORAGE_KEY}`), tp]);
    if (!res.ok) return [];
    const data = await res.json();
    return Array.isArray(data.teams) ? data.teams : [];
  } catch { return []; }
}
async function upsertTeam(entry) {
  try {
    const all = await loadAllTeams();
    const idx = all.findIndex(e => e.team === entry.team);
    if (idx >= 0) all[idx] = entry; else all.push(entry);
    all.sort((a, b) => b.total - a.total);
    const tp = new Promise((_, r) => setTimeout(() => r(new Error("timeout")), 4000));
    await Promise.race([fetch("/api/teams", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ key: STORAGE_KEY, teams: all }) }), tp]);
  } catch {}
}
async function clearAllTeams() {
  try { await fetch(`/api/teams?key=${STORAGE_KEY}`, { method: "DELETE" }); } catch {}
}

// ── 채점 ─────────────────────────────────────────────────────
function fallbackScore(answer) {
  const t = answer.trim();
  if (t.length < 50) return 0;
  const cv = ["고객","헌신","책임","공감","신뢰","혁신","창의","협력","파트너","친근","투명","윤리","규정","개선","소통","동료","팀"];
  const lg = ["따라서","때문에","그러므로","단계","첫째","둘째","먼저","다음으로"];
  const rs = ["합리적","효과적","실질적","근거","구체적","전략","제안"];
  const sl = ["해결","조치","보상","교체","환불","연락","처리","지원","대응","즉시"];
  const cvS = Math.min(10, 4 + cv.filter(k => t.includes(k)).length * 1.2);
  const lgS = Math.min(3.3, 1 + lg.filter(k => t.includes(k)).length * 0.8);
  const rsS = Math.min(3.3, 1 + rs.filter(k => t.includes(k)).length * 0.8);
  const slS = Math.min(3.3, 1 + sl.filter(k => t.includes(k)).length * 0.8);
  return Math.max(10, Math.min(20, Math.round(cvS + lgS + rsS + slS)));
}

function buildFallbackResult(answer) {
  const t = answer.trim();
  const cv = ["고객","헌신","책임","공감","신뢰","혁신","창의","협력","파트너","친근","투명","윤리","규정","개선","소통","동료","팀"];
  const lg = ["따라서","때문에","그러므로","단계","첫째","둘째","먼저","다음으로"];
  const rs = ["합리적","효과적","실질적","근거","구체적","전략","제안"];
  const sl = ["해결","조치","보상","교체","환불","연락","처리","지원","대응","즉시"];
  const cvH = cv.filter(k => t.includes(k));
  const lgH = lg.filter(k => t.includes(k));
  const rsH = rs.filter(k => t.includes(k));
  const slH = sl.filter(k => t.includes(k));
  const cvS = Math.min(10, 4 + cvH.length * 1.2);
  const lgS = Math.min(3.3, 1 + lgH.length * 0.8);
  const rsS = Math.min(3.3, 1 + rsH.length * 0.8);
  const slS = Math.min(3.3, 1 + slH.length * 0.8);
  const score = Math.max(10, Math.min(20, Math.round(cvS + lgS + rsS + slS)));
  return {
    score, isFallback: true,
    breakdown: { cv_value: Math.round(cvS*10)/10, logic: Math.round(lgS*10)/10, reason: Math.round(rsS*10)/10, solution: Math.round(slS*10)/10 },
    criteria_feedback: {
      cv_value: { score: Math.round(cvS*10)/10, max: 10, reason: cvH.length > 0 ? `CooperVision 핵심 키워드(${cvH.slice(0,3).join(", ")})가 사용되었습니다. 자동 채점 결과입니다.` : "CooperVision 가치 관련 키워드가 부족합니다. 자동 채점 결과입니다." },
      logic:    { score: Math.round(lgS*10)/10, max: 3.3, reason: lgH.length > 0 ? `논리 구조 키워드(${lgH.join(", ")})가 포함되어 있습니다.` : "논리적 흐름 키워드(따라서, 먼저 등)가 부족합니다." },
      reason:   { score: Math.round(rsS*10)/10, max: 3.3, reason: rsH.length > 0 ? `합리성 키워드(${rsH.join(", ")})가 포함되어 있습니다.` : "근거·전략 키워드(합리적, 구체적 등)가 부족합니다." },
      solution: { score: Math.round(slS*10)/10, max: 3.3, reason: slH.length > 0 ? `해결 방안 키워드(${slH.join(", ")})가 포함되어 있습니다.` : "실행 조치 키워드(해결, 즉시 등)가 부족합니다." },
    },
    strengths: t.length >= 100 ? "답변의 분량이 충분하여 기본 점수가 보장되었습니다." : "",
    improvements: "AI 채점 서버에 연결하지 못해 자동 채점되었습니다. CooperVision 가치와 구체적 실행 방안을 더 명확히 담으면 높은 점수를 받을 수 있습니다.",
    feedback: "자동 채점으로 대체되었습니다.",
  };
}

async function scoreWithAI(mission, caseItem, answer) {
  if (answer.trim().length < 50) return {
    score: 0, isFallback: false,
    breakdown: { cv_value: 0, logic: 0, reason: 0, solution: 0 },
    criteria_feedback: {
      cv_value: { score: 0, max: 10, reason: "답변이 50자 미만으로 채점되지 않습니다." },
      logic:    { score: 0, max: 3.3, reason: "답변이 50자 미만으로 채점되지 않습니다." },
      reason:   { score: 0, max: 3.3, reason: "답변이 50자 미만으로 채점되지 않습니다." },
      solution: { score: 0, max: 3.3, reason: "답변이 50자 미만으로 채점되지 않습니다." },
    },
    strengths: "", improvements: "", feedback: "답변이 50자 미만입니다.",
  };

  const prompt = `당신은 CooperVision 워크샵 전문 채점관입니다.\n\n${CV_VALUES}\n\n[이 존의 핵심 가치]\n${mission.zoneValue}\n\n[고객/상황 시나리오]\n제목: ${caseItem.title}\n상황: "${caseItem.quote}"\n배경: ${caseItem.background}\n\n[미션 질문]\n${mission.question}\n\n[참가자 답변]\n${answer}\n\n=== 채점 기준 (총 20점) ===\n50자 미만 → 0점 / 50자 이상 → 최소 10점 보장\n1. CooperVision 가치/문화 부합도 (최대 10점, 50%)\n2. 논리성 (최대 3.3점, 16.7%)\n3. 설명의 합리성 (최대 3.3점, 16.7%)\n4. 해결 가능성 (최대 3.3점, 16.7%)\n\n반드시 JSON만 출력:\n{"score":숫자(10-20),"breakdown":{"cv_value":숫자,"logic":숫자,"reason":숫자,"solution":숫자},"criteria_feedback":{"cv_value":{"score":숫자,"max":10,"reason":"근거 2문장"},"logic":{"score":숫자,"max":3.3,"reason":"근거 1-2문장"},"reason":{"score":숫자,"max":3.3,"reason":"근거 1-2문장"},"solution":{"score":숫자,"max":3.3,"reason":"근거 1-2문장"}},"strengths":"잘한 점 2-3문장","improvements":"개선할 점 2-3문장","feedback":"종합 2-3문장"}`;

  try {
    const tp = new Promise((_, r) => setTimeout(() => r(new Error("timeout")), AI_TIMEOUT_MS));
    // 주의: API 키를 프론트엔드에 두지 않기 위해 자체 백엔드(/api/score)를 통해 호출합니다.
    // 백엔드 구현은 api/score.js 를 참고하세요 (Vercel Serverless Function).
    const res = await Promise.race([fetch("/api/score", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt }) }), tp]);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await Promise.race([res.json(), tp]);
    const text = data.content?.map(c => c.text || "").join("") || "";
    const p = JSON.parse(text.replace(/```json|```/g, "").trim());
    if (typeof p.score === "number") { p.score = Math.max(10, Math.min(20, Math.round(p.score))); return { ...p, isFallback: false }; }
    throw new Error("invalid");
  } catch { return buildFallbackResult(answer); }
}

// ── 공통 UI ──────────────────────────────────────────────────
function CriteriaCard({ label, score, max, reason, color, weight }) {
  const pct = Math.min(100, (score / max) * 100);
  const grade = pct >= 80 ? "우수" : pct >= 60 ? "양호" : pct >= 40 ? "보통" : "미흡";
  const gc = pct >= 80 ? "#10B981" : pct >= 60 ? "#3B82F6" : pct >= 40 ? "#F59E0B" : "#EF4444";
  return (
    <div style={{ background: "#fff", borderRadius: 10, padding: "14px 16px", marginBottom: 10, border: "1px solid #E5E7EB" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
        <span style={{ fontSize: 13, fontWeight: 700, color: "#111", flex: 1 }}>{label}</span>
        <span style={{ fontSize: 10, color: "#9CA3AF" }}>{weight}</span>
        <span style={{ fontSize: 11, fontWeight: 700, color: gc, background: `${gc}15`, padding: "2px 8px", borderRadius: 10 }}>{grade}</span>
        <span style={{ fontSize: 14, fontWeight: 800, color }}>{typeof score === "number" ? score.toFixed(1) : "–"}<span style={{ fontSize: 11, color: "#9CA3AF", fontWeight: 400 }}>/{max.toFixed(1)}</span></span>
      </div>
      <div style={{ height: 5, background: "#F3F4F6", borderRadius: 3, marginBottom: 8 }}>
        <div style={{ height: "100%", width: `${pct}%`, background: color, borderRadius: 3 }} />
      </div>
      {reason && <div style={{ fontSize: 12, color: "#4B5563", lineHeight: 1.7, paddingLeft: 10, borderLeft: "2px solid #E5E7EB" }}>{reason}</div>}
    </div>
  );
}

function DetailedFeedback({ result, color, compact = false }) {
  const [show, setShow] = useState(!compact);
  if (!result) return null;
  const items = [
    { key: "cv_value", label: "CooperVision 가치 부합", max: 10, weight: "50%" },
    { key: "logic",    label: "논리성",                 max: 3.3, weight: "16.7%" },
    { key: "reason",   label: "설명의 합리성",           max: 3.3, weight: "16.7%" },
    { key: "solution", label: "해결 가능성",             max: 3.3, weight: "16.7%" },
  ];
  return (
    <div>
      {result.criteria_feedback && (
        <div style={{ marginBottom: 12 }}>
          {compact && (
            <button onClick={() => setShow(!show)} style={{ width: "100%", display: "flex", justifyContent: "space-between", padding: "8px 0", background: "transparent", border: "none", cursor: "pointer", marginBottom: 6 }}>
              <span style={{ fontSize: 12, fontWeight: 700, color: "#374151" }}>항목별 채점 근거</span>
              <span style={{ fontSize: 11, color: "#9CA3AF" }}>{show ? "▲ 접기" : "▼ 펼치기"}</span>
            </button>
          )}
          {!compact && <div style={{ fontSize: 12, fontWeight: 700, color: "#374151", marginBottom: 10 }}>항목별 채점 근거</div>}
          {show && items.map(item => {
            const cf = result.criteria_feedback[item.key];
            const sc = result.breakdown?.[item.key] ?? cf?.score ?? 0;
            return <CriteriaCard key={item.key} label={item.label} score={sc} max={item.max} reason={cf?.reason} color={color} weight={item.weight} />;
          })}
        </div>
      )}
      {result.strengths && (
        <div style={{ background: "#F0FFF8", borderRadius: 10, padding: "12px 14px", marginBottom: 8, borderLeft: "3px solid #10B981" }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#10B981", marginBottom: 5 }}>잘한 점</div>
          <div style={{ fontSize: 13, color: "#374151", lineHeight: 1.7 }}>{result.strengths}</div>
        </div>
      )}
      {result.improvements && (
        <div style={{ background: "#FFFBF0", borderRadius: 10, padding: "12px 14px", marginBottom: 8, borderLeft: "3px solid #F59E0B" }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#F59E0B", marginBottom: 5 }}>개선할 점</div>
          <div style={{ fontSize: 13, color: "#374151", lineHeight: 1.7 }}>{result.improvements}</div>
        </div>
      )}
      {!result.criteria_feedback && result.feedback && (
        <div style={{ background: "#F9FAFB", borderRadius: 10, padding: "12px 14px", marginBottom: 8 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", marginBottom: 5 }}>피드백</div>
          <div style={{ fontSize: 13, color: "#374151", lineHeight: 1.7 }}>{result.feedback}</div>
        </div>
      )}
    </div>
  );
}

// ── ZoneNavigator ─────────────────────────────────────────────
function ZoneNavigator({ missionIndex, selectedZones, scores, onNavigate }) {
  const pos = selectedZones.indexOf(missionIndex);
  const prevIdx = pos > 0 ? selectedZones[pos - 1] : null;
  const nextIdx = pos < selectedZones.length - 1 ? selectedZones[pos + 1] : null;
  const completedCount = selectedZones.filter(i => scores[i]).length;
  const canGoPrev = prevIdx !== null && scores[prevIdx] != null;
  const canGoNext = nextIdx !== null && scores[nextIdx] != null;

  return (
    <div style={{ marginBottom: 20 }}>
      {/* 존 진행 바 — 선택한 존만 */}
      <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
        {selectedZones.map(zIdx => {
          const m = MISSIONS[zIdx];
          const isDone = !!scores[zIdx];
          const isCurrent = zIdx === missionIndex;
          return (
            <div key={zIdx} onClick={() => isDone && onNavigate(zIdx)}
              title={isDone ? `${m.title} (완료)` : isCurrent ? "진행 중" : "미진행"}
              style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3, cursor: isDone ? "pointer" : "default" }}>
              <div style={{ width: "100%", height: 4, borderRadius: 2, background: isDone || isCurrent ? m.color : "#E5E7EB", opacity: isDone ? 1 : isCurrent ? 0.65 : 0.2 }} />
              <div style={{ display: "flex", alignItems: "center", gap: 2 }}>
                <span style={{ fontSize: 10, fontWeight: 700, color: isDone || isCurrent ? m.color : "#D1D5DB" }}>{m.zone}</span>
                {isDone && <span style={{ fontSize: 9, color: m.color }}>✓</span>}
              </div>
            </div>
          );
        })}
      </div>

      {/* < > 화살표 */}
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <button onClick={() => canGoPrev && onNavigate(prevIdx)} disabled={!canGoPrev}
          style={{ display: "flex", alignItems: "center", gap: 3, padding: "5px 12px", background: canGoPrev ? "#F3F4F6" : "#FAFAFA", border: `1px solid ${canGoPrev ? "#D1D5DB" : "#F3F4F6"}`, borderRadius: 8, cursor: canGoPrev ? "pointer" : "default", fontSize: 13, fontWeight: 700, color: canGoPrev ? "#374151" : "#D1D5DB" }}>
          ‹ {prevIdx !== null ? MISSIONS[prevIdx].zone : ""}
        </button>
        <div style={{ flex: 1, textAlign: "center", fontSize: 11, color: "#9CA3AF" }}>
          {completedCount} / {selectedZones.length} 완료
        </div>
        <button onClick={() => canGoNext && onNavigate(nextIdx)} disabled={!canGoNext}
          style={{ display: "flex", alignItems: "center", gap: 3, padding: "5px 12px", background: canGoNext ? "#F3F4F6" : "#FAFAFA", border: `1px solid ${canGoNext ? "#D1D5DB" : "#F3F4F6"}`, borderRadius: 8, cursor: canGoNext ? "pointer" : "default", fontSize: 13, fontWeight: 700, color: canGoNext ? "#374151" : "#D1D5DB" }}>
          {nextIdx !== null ? MISSIONS[nextIdx].zone : ""} ›
        </button>
      </div>
    </div>
  );
}

// ── 리포트 화면 ───────────────────────────────────────────────
function ReportScreen({ teamName, missionIndex, result, selectedCase, mission, onClose }) {
  const items = [
    { key: "cv_value", label: "CooperVision 가치 부합", max: 10, weight: "50%", desc: "핵심 가치가 답변에 실질적으로 반영되었는가?" },
    { key: "logic",    label: "논리성",                 max: 3.3, weight: "16.7%", desc: "문제→원인→해결의 흐름이 체계적인가?" },
    { key: "reason",   label: "설명의 합리성",           max: 3.3, weight: "16.7%", desc: "해결책의 근거가 납득 가능한가?" },
    { key: "solution", label: "해결 가능성",             max: 3.3, weight: "16.7%", desc: "실제 현업에서 실행 가능한 방안인가?" },
  ];
  const pct = Math.round((result.score / 20) * 100);
  const grade = pct >= 90 ? "S" : pct >= 75 ? "A" : pct >= 60 ? "B" : pct >= 40 ? "C" : "D";
  const gc = pct >= 90 ? "#7C3AED" : pct >= 75 ? "#059669" : pct >= 60 ? "#0284C7" : pct >= 40 ? "#F59E0B" : "#EF4444";
  return (
    <div style={{ minHeight: "100vh", background: "#F8F9FA" }}>
      <div style={{ background: "#fff", borderBottom: "1px solid #E5E7EB", padding: "14px 20px", display: "flex", alignItems: "center", gap: 12, position: "sticky", top: 0, zIndex: 10 }}>
        <button onClick={onClose} style={{ padding: "6px 12px", background: "#F3F4F6", border: "none", borderRadius: 8, fontSize: 13, cursor: "pointer", color: "#374151" }}>← 돌아가기</button>
        <div style={{ flex: 1, textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#9CA3AF", letterSpacing: 1 }}>COOPERVISION VALUE WORKSHOP</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#111" }}>채점 리포트</div>
        </div>
        <div style={{ fontSize: 11, color: "#9CA3AF" }}>{mission.zone} 존</div>
      </div>
      <div style={{ maxWidth: 600, margin: "0 auto", padding: "20px 20px 40px" }}>
        {/* 점수 헤더 */}
        <div style={{ background: "#fff", borderRadius: 16, padding: "24px", marginBottom: 16, border: "1px solid #E5E7EB", textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#9CA3AF", marginBottom: 4 }}>{teamName}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 12, justifyContent: "center", marginBottom: 8 }}>
            <div style={{ width: 40, height: 40, borderRadius: "50%", background: mission.color, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Georgia, serif", fontSize: 20, fontWeight: 700 }}>{mission.zone}</div>
            <div style={{ fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700, color: "#111" }}>{mission.title}</div>
          </div>
          {selectedCase && <div style={{ fontSize: 12, color: "#6B7280", marginBottom: 16 }}>{selectedCase.num} · {selectedCase.title}</div>}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 24 }}>
            <div><div style={{ fontFamily: "Georgia, serif", fontSize: 56, fontWeight: 800, color: mission.color, lineHeight: 1 }}>{result.score}</div><div style={{ fontSize: 12, color: "#6B7280" }}>/ 20점</div></div>
            <div style={{ width: 1, height: 60, background: "#E5E7EB" }} />
            <div><div style={{ fontFamily: "Georgia, serif", fontSize: 56, fontWeight: 800, color: gc, lineHeight: 1 }}>{grade}</div><div style={{ fontSize: 12, color: "#6B7280" }}>등급</div></div>
          </div>
          <div style={{ marginTop: 16, height: 8, background: "#F3F4F6", borderRadius: 4 }}>
            <div style={{ height: "100%", width: `${pct}%`, background: mission.color, borderRadius: 4 }} />
          </div>
          <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 4 }}>{pct}% 달성</div>
          {result.isFallback && <div style={{ marginTop: 8, fontSize: 11, color: "#F59E0B", background: "#FFFBF0", padding: "4px 12px", borderRadius: 20, display: "inline-block" }}>⚠ 자동 채점</div>}
        </div>
        {/* 항목별 상세 */}
        <div style={{ background: "#fff", borderRadius: 16, padding: "20px", marginBottom: 16, border: "1px solid #E5E7EB" }}>
          <div style={{ fontFamily: "Georgia, serif", fontSize: 16, fontWeight: 700, color: "#111", marginBottom: 16, paddingBottom: 10, borderBottom: "1px solid #E5E7EB" }}>항목별 채점 결과</div>
          {items.map((item, idx) => {
            const cf = result.criteria_feedback?.[item.key];
            const sc = result.breakdown?.[item.key] ?? cf?.score ?? 0;
            const ip = Math.min(100, (sc / item.max) * 100);
            const ig = ip >= 80 ? { l: "우수", c: "#059669", b: "#F0FFF8" } : ip >= 60 ? { l: "양호", c: "#0284C7", b: "#EFF6FF" } : ip >= 40 ? { l: "보통", c: "#F59E0B", b: "#FFFBF0" } : { l: "미흡", c: "#EF4444", b: "#FFF1F2" };
            return (
              <div key={item.key} style={{ marginBottom: idx < items.length - 1 ? 20 : 0, paddingBottom: idx < items.length - 1 ? 20 : 0, borderBottom: idx < items.length - 1 ? "1px solid #F3F4F6" : "none" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                  <div style={{ width: 28, height: 28, borderRadius: "50%", background: `${mission.color}15`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, color: mission.color, flexShrink: 0 }}>{idx + 1}</div>
                  <div style={{ flex: 1 }}><div style={{ fontSize: 14, fontWeight: 700, color: "#111" }}>{item.label}</div><div style={{ fontSize: 11, color: "#9CA3AF" }}>{item.desc} · {item.weight}</div></div>
                  <div><span style={{ fontSize: 11, fontWeight: 700, color: ig.c, background: ig.b, padding: "2px 8px", borderRadius: 10, marginRight: 6 }}>{ig.l}</span><span style={{ fontSize: 16, fontWeight: 800, color: mission.color }}>{typeof sc === "number" ? sc.toFixed(1) : "–"}</span><span style={{ fontSize: 11, color: "#9CA3AF" }}>/{item.max.toFixed(1)}</span></div>
                </div>
                <div style={{ height: 6, background: "#F3F4F6", borderRadius: 3, marginBottom: 10, marginLeft: 38 }}><div style={{ height: "100%", width: `${ip}%`, background: mission.color, borderRadius: 3 }} /></div>
                {cf?.reason && <div style={{ marginLeft: 38, background: "#F8F9FA", borderRadius: 8, padding: "10px 14px", borderLeft: `3px solid ${mission.color}` }}><div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", marginBottom: 4 }}>채점 근거</div><div style={{ fontSize: 13, color: "#374151", lineHeight: 1.7 }}>{cf.reason}</div></div>}
              </div>
            );
          })}
        </div>
        {/* 종합 피드백 */}
        <div style={{ background: "#fff", borderRadius: 16, padding: "20px", marginBottom: 16, border: "1px solid #E5E7EB" }}>
          <div style={{ fontFamily: "Georgia, serif", fontSize: 16, fontWeight: 700, color: "#111", marginBottom: 16, paddingBottom: 10, borderBottom: "1px solid #E5E7EB" }}>종합 피드백</div>
          {result.strengths && <div style={{ marginBottom: 12 }}><div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}><div style={{ width: 20, height: 20, borderRadius: "50%", background: "#10B981", display: "flex", alignItems: "center", justifyContent: "center" }}><span style={{ color: "#fff", fontSize: 12, fontWeight: 700 }}>+</span></div><span style={{ fontSize: 13, fontWeight: 700, color: "#10B981" }}>잘한 점</span></div><div style={{ fontSize: 13, color: "#374151", lineHeight: 1.8, paddingLeft: 28 }}>{result.strengths}</div></div>}
          {result.improvements && <div><div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}><div style={{ width: 20, height: 20, borderRadius: "50%", background: "#F59E0B", display: "flex", alignItems: "center", justifyContent: "center" }}><span style={{ color: "#fff", fontSize: 12, fontWeight: 700 }}>↑</span></div><span style={{ fontSize: 13, fontWeight: 700, color: "#F59E0B" }}>개선할 점</span></div><div style={{ fontSize: 13, color: "#374151", lineHeight: 1.8, paddingLeft: 28 }}>{result.improvements}</div></div>}
        </div>
        {/* 가이드 */}
        <div style={{ background: mission.bg, borderRadius: 16, padding: "20px", border: `1px solid ${mission.color}20` }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: mission.color, marginBottom: 8 }}>{mission.title} 핵심 가이드</div>
          <div style={{ fontSize: 13, color: "#4B5563", lineHeight: 1.7 }}>{mission.zoneValue}</div>
          <div style={{ marginTop: 8, fontSize: 12, color: "#6B7280", lineHeight: 1.6 }}>다음 번에는 이 가치를 답변의 도입부에서 명확히 언급하고 구체적 실행 방안과 연결해보세요.</div>
        </div>
      </div>
    </div>
  );
}

