// ── 존 선택 화면 ──────────────────────────────────────────────
function ZoneSelectScreen({ teamName, onStart, onBack }) {
  const [selected, setSelected] = useState(MISSIONS.map((_, i) => i));
  const toggle = (i) => setSelected(prev => prev.includes(i) ? prev.filter(x => x !== i) : [...prev, i].sort((a, b) => a - b));
  return (
    <div style={S.screen}><div style={S.card}>
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#9CA3AF", letterSpacing: 3, marginBottom: 6 }}>COOPERVISION VALUE WORKSHOP</div>
        <div style={{ fontFamily: "Georgia, serif", fontSize: 22, fontWeight: 700, color: "#111", marginBottom: 4 }}>진행할 존을 선택하세요</div>
        <div style={{ fontSize: 13, color: "#6B7280" }}><span style={{ fontWeight: 600, color: "#111" }}>{teamName}</span> 팀</div>
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <button onClick={() => setSelected(MISSIONS.map((_, i) => i))} style={{ flex: 1, padding: "8px", fontSize: 12, fontWeight: 600, color: selected.length === MISSIONS.length ? "#fff" : "#374151", background: selected.length === MISSIONS.length ? "#1E1B4B" : "#F3F4F6", border: "none", borderRadius: 8, cursor: "pointer" }}>전체 선택</button>
        <button onClick={() => setSelected([])} style={{ flex: 1, padding: "8px", fontSize: 12, fontWeight: 600, color: "#6B7280", background: "#F3F4F6", border: "none", borderRadius: 8, cursor: "pointer" }}>전체 해제</button>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 16 }}>
        {MISSIONS.map((m, i) => {
          const isOn = selected.includes(i);
          return (
            <button key={m.id} onClick={() => toggle(i)}
              style={{ width: "100%", display: "flex", alignItems: "center", gap: 14, padding: "14px 16px", background: isOn ? m.bg : "#FAFAFA", border: `1.5px solid ${isOn ? m.color : "#E5E7EB"}`, borderRadius: 14, cursor: "pointer", textAlign: "left", transition: "all 0.15s" }}>
              <div style={{ width: 42, height: 42, borderRadius: "50%", background: isOn ? "transparent" : "#F3F4F6", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: isOn ? 1 : 0.4, transition: "all 0.15s" }}>
                {isOn ? ZONE_ICONS[m.zone] : <div style={{ width: 42, height: 42, borderRadius: "50%", background: "#E5E7EB", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700, color: "#aaa" }}>{m.zone}</div>}
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: isOn ? "#111" : "#9CA3AF" }}>{m.title}</div>
                <div style={{ fontSize: 11, color: isOn ? m.color : "#C4C4C4", fontWeight: 600, marginTop: 2 }}>{m.description.split("\n")[0]}</div>
              </div>
              <div style={{ width: 24, height: 24, borderRadius: "50%", background: isOn ? m.color : "#E5E7EB", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                {isOn && <span style={{ color: "#fff", fontSize: 13, fontWeight: 700 }}>✓</span>}
              </div>
            </button>
          );
        })}
      </div>

      {/* 선택 요약 */}
      <div style={{ background: "#F9FAFB", borderRadius: 12, padding: "12px 16px", marginBottom: 14, display: "flex", alignItems: "center", gap: 10 }}>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 11, color: "#6B7280", marginBottom: 4 }}>선택된 존</div>
          <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
            {selected.length === 0
              ? <span style={{ fontSize: 12, color: "#D1D5DB" }}>없음 (최소 1개 선택)</span>
              : selected.map(i => <span key={i} style={{ fontSize: 11, fontWeight: 700, color: "#fff", background: MISSIONS[i].color, padding: "2px 8px", borderRadius: 20 }}>{MISSIONS[i].zone}</span>)}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontFamily: "Georgia, serif", fontSize: 24, fontWeight: 700, color: "#111" }}>{selected.length}</div>
          <div style={{ fontSize: 11, color: "#9CA3AF" }}>/ {MISSIONS.length}개</div>
        </div>
      </div>

      <button onClick={() => selected.length > 0 && onStart(selected)}
        style={{ ...S.btn, opacity: selected.length > 0 ? 1 : 0.4, cursor: selected.length > 0 ? "pointer" : "default", marginBottom: 10 }}>
        {selected.length > 0 ? `${selected.length}개 존 시작하기 →` : "최소 1개 이상 선택해주세요"}
      </button>
      <button onClick={onBack} style={{ width: "100%", padding: "10px", fontSize: 13, color: "#9CA3AF", background: "transparent", border: "none", cursor: "pointer" }}>← 뒤로</button>
    </div></div>
  );
}

// ── 미션 화면 ─────────────────────────────────────────────────
function MissionScreen({ teamName, missionIndex, selectedZones, scores, onNext, onGoTower, onNavigate }) {
  const mission = MISSIONS[missionIndex];
  const existingResult = scores[missionIndex] || null;
  const [phase, setPhase] = useState(existingResult ? "result" : "select");
  const [selectedCase, setSelectedCase] = useState(null);
  const [answer, setAnswer] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(existingResult);
  const [transitioning, setTransitioning] = useState(false);
  const [showReport, setShowReport] = useState(false);
  const [showMyAnswer, setShowMyAnswer] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [editAnswer, setEditAnswer] = useState("");

  const charCount = answer.trim().length;
  const runningTotal = Object.values(scores).reduce((a, b) => a + (b?.score || 0), 0);
  const pos = selectedZones.indexOf(missionIndex);
  const isLast = pos === selectedZones.length - 1;

  const handleSubmit = async () => {
    if (!answer.trim() || loading) return;
    setLoading(true);
    const res = await scoreWithAI(mission, selectedCase, answer);
    setResult({ ...res, myAnswer: answer });
    setLoading(false); setPhase("result");
  };

  const handleGoNext = () => {
    if (transitioning) return;
    setTransitioning(true);
    onNext(missionIndex, result);
  };

  const resetForRetry = () => { setPhase("select"); setResult(null); setAnswer(""); setSelectedCase(null); setTransitioning(false); setShowMyAnswer(false); setEditMode(false); };

  if (showReport && result) return <ReportScreen teamName={teamName} missionIndex={missionIndex} result={result} selectedCase={selectedCase} mission={mission} onClose={() => setShowReport(false)} />;

  return (
    <div style={S.screen}><div style={S.card}>
      {/* 헤더 */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <span style={{ fontSize: 13, color: "#6B7280", fontWeight: 500 }}>{teamName}</span>
        <span style={{ fontSize: 12, color: "#9CA3AF", background: "#F3F4F6", padding: "3px 10px", borderRadius: 20 }}>누적 {runningTotal}점 · {pos + 1}/{selectedZones.length}</span>
      </div>

      <ZoneNavigator missionIndex={missionIndex} selectedZones={selectedZones} scores={scores} onNavigate={onNavigate} />

      {/* 존 헤더 */}
      <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 16px", borderRadius: 12, background: mission.bg, marginBottom: 22 }}>
        <div style={{ width: 52, height: 52, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, boxShadow: `0 4px 16px ${mission.color}55` }}>
          {ZONE_ICONS[mission.zone] ? <div style={{ transform: "scale(1.8)", transformOrigin: "center" }}>{ZONE_ICONS[mission.zone]}</div> : <div style={{ width: 52, height: 52, borderRadius: "50%", background: mission.color, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Georgia, serif", fontSize: 22, fontWeight: 700 }}>{mission.zone}</div>}
        </div>
        <div>
          <div style={{ fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700, color: "#111" }}>{mission.title}</div>
          {mission.description.split("\n").map((line, i) => (
            <div key={i} style={{ fontSize: i === 0 ? 12 : 11, color: i === 0 ? "#555" : "#6B7280", fontWeight: i === 0 ? 600 : 400, marginTop: i === 0 ? 3 : 1 }}>{line}</div>
          ))}
        </div>
      </div>

      {/* PHASE: select */}
      {phase === "select" && (
        <div>
          <div style={{ fontSize: 14, fontWeight: 600, color: "#374151", textAlign: "center", marginBottom: 4 }}>시나리오를 선택하세요</div>
          <div style={{ fontSize: 12, color: "#9CA3AF", textAlign: "center", marginBottom: 18 }}>제목을 고르면 상세 내용이 공개됩니다</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {mission.cases.map((c, i) => (
              <button key={i} onClick={() => { setSelectedCase(c); setPhase("detail"); }}
                style={{ width: "100%", padding: "18px 20px", background: "#fff", border: `1.5px solid ${mission.color}25`, borderRadius: 14, cursor: "pointer", textAlign: "left", display: "flex", alignItems: "center", gap: 16, transition: "all 0.15s" }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = mission.color; e.currentTarget.style.background = mission.bg; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = `${mission.color}25`; e.currentTarget.style.background = "#fff"; }}>
                <div style={{ width: 36, height: 36, borderRadius: "50%", background: `${mission.color}15`, color: mission.color, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14, fontWeight: 700, flexShrink: 0 }}>{i + 1}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 11, color: mission.color, fontWeight: 600, marginBottom: 3 }}>{c.num}</div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: "#111" }}>{c.title}</div>
                </div>
                <span style={{ fontSize: 20, color: `${mission.color}50` }}>→</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* PHASE: detail */}
      {phase === "detail" && selectedCase && (
        <div>
          <div style={{ background: "#F9FAFB", borderRadius: 14, padding: "18px", borderLeft: `4px solid ${mission.color}`, marginBottom: 14 }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: "#111", marginBottom: 12 }}>{selectedCase.title}</div>
            <div style={{ background: "#fff", borderRadius: 10, padding: "12px 14px", marginBottom: 12 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: "#9CA3AF", marginBottom: 6, textTransform: "uppercase", letterSpacing: 0.8 }}>{selectedCase.num.startsWith("액티비티") ? "활동 안내" : "상황"}</div>
              <div style={{ fontSize: 14, color: "#1F2937", lineHeight: 1.8, fontStyle: selectedCase.num.startsWith("액티비티") ? "normal" : "italic", paddingLeft: 12, borderLeft: `3px solid ${mission.color}` }}>
                {selectedCase.num.startsWith("액티비티")
                  ? selectedCase.quote.split("\n").map((line, i) => line === "" ? <br key={i}/> : <span key={i} style={{ display: "block", marginBottom: line.startsWith("【") ? 6 : line.startsWith("•") || line.startsWith("①") || line.startsWith("▶") ? 2 : 0, fontWeight: line.startsWith("【") ? 700 : 400, color: line.startsWith("【") ? mission.color : "#1F2937" }}>{line}</span>)
                  : `"${selectedCase.quote}"`}
              </div>
            </div>
            <div style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: "#9CA3AF", marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.8 }}>상황 배경</div>
              <div style={{ fontSize: 13, color: "#4B5563", lineHeight: 1.6 }}>
                {selectedCase.background.split("\n").map((line, i) => (
                  line === "" ? <br key={i} /> :
                  <span key={i} style={{ display: "block", marginBottom: 3, fontWeight: line.startsWith("【") ? 700 : 400, color: line.startsWith("【") ? "#374151" : "#4B5563" }}>{line}</span>
                ))}
              </div>
            </div>
            <span style={{ display: "inline-block", fontSize: 12, fontWeight: 600, padding: "4px 12px", borderRadius: 20, background: mission.tagBg, color: mission.tagColor }}>핵심 역량: {selectedCase.skill}</span>
          </div>
          <div style={{ background: "#111", borderRadius: 10, padding: "14px 16px", marginBottom: 18, fontSize: 15, color: "#fff", lineHeight: 1.6, fontWeight: 500 }}>Q. {mission.question}</div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={() => { setSelectedCase(null); setPhase("select"); }} style={{ flex: 1, padding: "13px", fontSize: 14, fontWeight: 600, color: "#6B7280", background: "#F3F4F6", border: "none", borderRadius: 12, cursor: "pointer" }}>← 다시 선택</button>
            <button onClick={() => setPhase("answer")} style={{ flex: 2, ...S.btn, background: mission.color, boxShadow: `0 4px 20px ${mission.color}44` }}>답변 작성하기 →</button>
          </div>
        </div>
      )}

      {/* PHASE: answer */}
      {phase === "answer" && selectedCase && (
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderRadius: 10, background: mission.bg, marginBottom: 14, border: `1px solid ${mission.color}30` }}>
            <span style={{ background: mission.color, color: "#fff", padding: "2px 8px", borderRadius: 20, fontSize: 11, fontWeight: 700, flexShrink: 0 }}>{selectedCase.num}</span>
            <span style={{ fontSize: 13, fontWeight: 600, color: "#111", flex: 1 }}>{selectedCase.title}</span>
            <button onClick={() => setPhase("detail")} style={{ fontSize: 11, color: mission.color, background: "transparent", border: "none", cursor: "pointer", fontWeight: 600 }}>상세 보기</button>
          </div>
          <div style={{ background: "#111", borderRadius: 10, padding: "12px 16px", marginBottom: 14, fontSize: 14, color: "#fff", lineHeight: 1.6, fontWeight: 500 }}>Q. {mission.question}</div>
          <textarea style={{ ...S.textarea, borderColor: charCount > 0 ? mission.color : "#E5E7EB" }} placeholder="CooperVision 가치를 담아 답변을 작성하세요..." value={answer} onChange={e => setAnswer(e.target.value)} rows={6} disabled={loading} autoFocus />
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 12, fontWeight: 600, color: charCount < 50 ? "#F59E0B" : "#10B981" }}>{charCount}자</span>
              {charCount < 50 ? <span style={{ fontSize: 11, color: "#F59E0B" }}>({50 - charCount}자 더 쓰면 최소 10점)</span> : <span style={{ fontSize: 11, color: "#10B981" }}>최소 10점 보장 ✓</span>}
            </div>
          </div>
          {loading && (
            <div style={{ background: mission.bg, borderRadius: 12, padding: "14px", marginBottom: 14, textAlign: "center" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10, marginBottom: 4 }}>
                <span style={S.spinner} /><span style={{ fontSize: 14, fontWeight: 600, color: mission.color }}>AI 채점 중...</span>
              </div>
              <div style={{ fontSize: 12, color: "#9CA3AF" }}>최대 25초</div>
            </div>
          )}
          <button style={{ ...S.btn, background: mission.color, boxShadow: `0 4px 20px ${mission.color}44`, opacity: answer.trim() && !loading ? 1 : 0.4, cursor: answer.trim() && !loading ? "pointer" : "default" }} onClick={handleSubmit}>
            {loading ? "채점 중..." : "제출 & AI 채점 →"}
          </button>
        </div>
      )}

      {/* PHASE: result */}
      {phase === "result" && result && (
        <div>
          {/* 내 답변 보기 모달 */}
          {showMyAnswer && result.myAnswer && (
            <div style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, background: "rgba(0,0,0,0.5)", zIndex: 100, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
              <div style={{ background: "#fff", borderRadius: 16, padding: "22px", maxWidth: 480, width: "100%", maxHeight: "80vh", overflow: "auto" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#111" }}>내 답변</div>
                  <button onClick={() => setShowMyAnswer(false)} style={{ fontSize: 18, color: "#9CA3AF", background: "transparent", border: "none", cursor: "pointer" }}>✕</button>
                </div>
                {!editMode ? (
                  <>
                    <div style={{ background: "#F9FAFB", borderRadius: 10, padding: "14px", fontSize: 14, color: "#1F2937", lineHeight: 1.8, marginBottom: 14, borderLeft: `3px solid ${mission.color}`, whiteSpace: "pre-wrap" }}>
                      {result.myAnswer}
                    </div>
                    <div style={{ fontSize: 11, color: "#9CA3AF", marginBottom: 14 }}>{result.myAnswer.length}자</div>
                    <div style={{ display: "flex", gap: 8 }}>
                      <button onClick={() => { setEditAnswer(result.myAnswer); setEditMode(true); }}
                        style={{ flex: 1, padding: "11px", fontSize: 13, fontWeight: 600, color: mission.color, background: `${mission.color}12`, border: `1.5px solid ${mission.color}`, borderRadius: 10, cursor: "pointer" }}>
                        ✏️ 답변 수정하기
                      </button>
                      <button onClick={() => setShowMyAnswer(false)}
                        style={{ flex: 1, padding: "11px", fontSize: 13, fontWeight: 600, color: "#6B7280", background: "#F3F4F6", border: "none", borderRadius: 10, cursor: "pointer" }}>
                        닫기
                      </button>
                    </div>
                  </>
                ) : (
                  <>
                    <textarea
                      value={editAnswer}
                      onChange={e => setEditAnswer(e.target.value)}
                      style={{ ...S.textarea, minHeight: 160, borderColor: mission.color }}
                      autoFocus
                    />
                    <div style={{ fontSize: 11, color: editAnswer.trim().length < 50 ? "#F59E0B" : "#10B981", marginBottom: 14 }}>
                      {editAnswer.trim().length}자 {editAnswer.trim().length < 50 ? `(${50 - editAnswer.trim().length}자 더 필요)` : "✓"}
                    </div>
                    <div style={{ display: "flex", gap: 8 }}>
                      <button onClick={async () => {
                        if (!editAnswer.trim() || editAnswer.trim() === result.myAnswer) { setEditMode(false); return; }
                        setShowMyAnswer(false); setEditMode(false);
                        setLoading(true); setPhase("result");
                        const newRes = await scoreWithAI(mission, selectedCase, editAnswer);
                        setResult({ ...newRes, myAnswer: editAnswer });
                        setLoading(false);
                      }} style={{ flex: 2, padding: "11px", fontSize: 13, fontWeight: 700, color: "#fff", background: mission.color, border: "none", borderRadius: 10, cursor: "pointer" }}>
                        재채점하기 →
                      </button>
                      <button onClick={() => setEditMode(false)}
                        style={{ flex: 1, padding: "11px", fontSize: 13, fontWeight: 600, color: "#6B7280", background: "#F3F4F6", border: "none", borderRadius: 10, cursor: "pointer" }}>
                        취소
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>
          )}

          <div style={{ textAlign: "center", padding: "20px", background: mission.bg, borderRadius: 14, border: `1.5px solid ${mission.color}30`, marginBottom: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 600, color: mission.color, letterSpacing: 1, marginBottom: 6 }}>
              {result.isFallback ? "자동 채점" : "AI 채점"}{selectedCase ? ` · ${selectedCase.num}` : ""}
            </div>
            <div style={{ fontFamily: "Georgia, serif", fontSize: 60, fontWeight: 800, color: mission.color, lineHeight: 1, marginBottom: 2 }}>{result.score}</div>
            <div style={{ fontSize: 13, color: "#6B7280", marginBottom: 12 }}>/ {MAX_SCORE}점</div>
            <div style={{ display: "flex", gap: 8, justifyContent: "center" }}>
              <button onClick={() => setShowReport(true)} style={{ fontSize: 12, fontWeight: 600, color: mission.color, background: "transparent", border: `1.5px solid ${mission.color}`, borderRadius: 20, padding: "5px 16px", cursor: "pointer" }}>
                상세 리포트 보기 →
              </button>
              <button onClick={() => { setShowMyAnswer(true); setEditMode(false); }} style={{ fontSize: 12, fontWeight: 600, color: "#6B7280", background: "transparent", border: "1.5px solid #D1D5DB", borderRadius: 20, padding: "5px 16px", cursor: "pointer" }}>
                내 답변 보기 ✏️
              </button>
            </div>
          </div>

          <DetailedFeedback result={result} color={mission.color} compact={true} />

          <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
            <button onClick={resetForRetry} style={{ flex: 1, padding: "14px", fontSize: 13, fontWeight: 600, color: "#6B7280", background: "#F3F4F6", border: "none", borderRadius: 12, cursor: "pointer" }}>
              ↺ 다시 답변
            </button>
            <button style={{ flex: 2, ...S.btn, background: mission.color, boxShadow: `0 4px 20px ${mission.color}44`, opacity: transitioning ? 0.5 : 1, cursor: transitioning ? "default" : "pointer" }} onClick={handleGoNext}>
              {transitioning ? "이동 중..." : isLast ? "최종 결과 보기 →" : `다음: ${MISSIONS[selectedZones[pos + 1]]?.title} →`}
            </button>
          </div>
        </div>
      )}
    </div></div>
  );
}

// ── 최종 결과 화면 ────────────────────────────────────────────
function FinalScreen({ teamName, selectedZones, scores, onRestart, onGoTower }) {
  const scoreList = selectedZones.map(i => scores[i]).filter(Boolean);
  const total = scoreList.reduce((a, b) => a + b.score, 0);
  const maxTotal = selectedZones.length * MAX_SCORE;
  const pct = Math.round((total / maxTotal) * 100);
  const [expanded, setExpanded] = useState(null);
  const [reportTarget, setReportTarget] = useState(null);

  if (reportTarget !== null && scores[reportTarget]) {
    return <ReportScreen teamName={teamName} missionIndex={reportTarget} result={scores[reportTarget]} selectedCase={null} mission={MISSIONS[reportTarget]} onClose={() => setReportTarget(null)} />;
  }

  return (
    <div style={S.screen}><div style={S.card}>
      <div style={{ textAlign: "center", marginBottom: 22 }}>
        <div style={{ fontSize: 36, marginBottom: 8 }}>🎉</div>
        <div style={{ fontFamily: "Georgia, serif", fontSize: 24, fontWeight: 700, color: "#111" }}>미션 완료!</div>
        <div style={{ fontSize: 13, color: "#6B7280", marginTop: 4 }}>{teamName}의 최종 결과</div>
      </div>

      <div style={{ background: "linear-gradient(135deg, #1E1B4B 0%, #312E81 100%)", borderRadius: 16, padding: "20px 24px", marginBottom: 20, color: "#fff", textAlign: "center" }}>
        <div style={{ fontSize: 12, opacity: 0.7, marginBottom: 4 }}>총 점수</div>
        <div style={{ fontFamily: "Georgia, serif", fontSize: 56, fontWeight: 700, lineHeight: 1 }}>{total}</div>
        <div style={{ fontSize: 13, opacity: 0.6, marginBottom: 16 }}>/ {maxTotal}점 ({pct}%)</div>
        <div style={{ display: "flex", gap: 8, justifyContent: "center" }}>
          {selectedZones.map(i => {
            const s = scores[i];
            return (
              <div key={i} style={{ flex: 1, maxWidth: 60, textAlign: "center" }}>
                <div style={{ height: 36, background: "rgba(255,255,255,0.12)", borderRadius: 4, display: "flex", alignItems: "flex-end", overflow: "hidden", marginBottom: 4 }}>
                  <div style={{ width: "100%", height: s ? `${(s.score / MAX_SCORE) * 100}%` : "0%", background: MISSIONS[i].color, borderRadius: 3 }} />
                </div>
                <div style={{ fontSize: 10, opacity: 0.7 }}>{MISSIONS[i].zone}</div>
                <div style={{ fontSize: 11, fontWeight: 700 }}>{s ? s.score : "–"}</div>
              </div>
            );
          })}
        </div>
      </div>

      <div style={{ marginBottom: 20 }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: "#374151", marginBottom: 10 }}>존별 상세 피드백</div>
        {selectedZones.map(i => {
          const s = scores[i];
          const m = MISSIONS[i];
          const open = expanded === i;
          if (!s) return null;
          return (
            <div key={i} style={{ marginBottom: 8, border: `1px solid ${open ? m.color : "#E5E7EB"}`, borderRadius: 12, overflow: "hidden" }}>
              <div style={{ display: "flex", alignItems: "center", background: open ? m.bg : "#fff" }}>
                <button onClick={() => setExpanded(open ? null : i)} style={{ flex: 1, display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", background: "transparent", border: "none", cursor: "pointer", textAlign: "left" }}>
                  <div style={{ width: 30, height: 30, borderRadius: "50%", background: m.color, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, flexShrink: 0 }}>{m.zone}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: "#111" }}>{m.title}</div>
                    <div style={{ height: 3, background: "#E5E7EB", borderRadius: 2, marginTop: 4 }}><div style={{ height: "100%", width: `${(s.score / MAX_SCORE) * 100}%`, background: m.color, borderRadius: 2 }} /></div>
                  </div>
                  <div style={{ fontFamily: "Georgia, serif", fontSize: 20, fontWeight: 700, color: m.color }}>{s.score}점</div>
                  <span style={{ fontSize: 11, color: "#9CA3AF" }}>{open ? "▲" : "▼"}</span>
                </button>
                <button onClick={() => setReportTarget(i)} style={{ padding: "6px 12px", margin: "0 8px", fontSize: 11, fontWeight: 600, color: m.color, background: `${m.color}15`, border: "none", borderRadius: 16, cursor: "pointer", whiteSpace: "nowrap" }}>리포트</button>
              </div>
              {open && <div style={{ padding: "0 16px 16px", background: m.bg }}><DetailedFeedback result={s} color={m.color} compact={true} /></div>}
            </div>
          );
        })}
      </div>

      <div style={{ display: "flex", gap: 10 }}>
        <button style={{ ...S.btn, background: "#374151", flex: 1 }} onClick={onRestart}>처음으로</button>
        <button onClick={onGoTower} style={{ flex: 1, padding: "14px", fontSize: 14, fontWeight: 600, color: "#6B7280", background: "transparent", border: "1.5px solid #D1D5DB", borderRadius: 12, cursor: "pointer" }}>강사 모드 →</button>
      </div>
    </div></div>
  );
}

// ── 강사 Control Tower ────────────────────────────────────────
function ControlTower({ onExit }) {
  const [teams, setTeams] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedTeam, setSelectedTeam] = useState(null);
  const [zoneFilter, setZoneFilter] = useState(null);
  const [lastRefresh, setLastRefresh] = useState("–");
  const [confirmClear, setConfirmClear] = useState(false);

  const refresh = async () => {
    setLoading(true);
    try { const d = await loadAllTeams(); setTeams(d); setLastRefresh(new Date().toLocaleTimeString("ko-KR")); }
    catch {} finally { setLoading(false); }
  };

  useEffect(() => { refresh(); const t = setInterval(refresh, 15000); return () => clearInterval(t); }, []);

  const handleClear = async () => { await clearAllTeams(); setTeams([]); setConfirmClear(false); setSelectedTeam(null); setLastRefresh(new Date().toLocaleTimeString("ko-KR")); };

  const seedTestData = async () => {
    const mk = (base) => MISSIONS.map((_, j) => ({
      score: Math.max(10, Math.min(20, base + j - 1)),
      isFallback: false,
      breakdown: { cv_value: Math.min(10, (base/2) + j*0.3), logic: 2.0 + j*0.1, reason: 1.8 + j*0.1, solution: 2.1 + j*0.1 },
      criteria_feedback: {
        cv_value: { score: Math.min(10, (base/2)+j*0.3), max: 10, reason: "CooperVision 핵심 가치가 답변에 잘 반영되었습니다." },
        logic:    { score: 2.0+j*0.1, max: 3.3, reason: "논리 구조가 체계적입니다." },
        reason:   { score: 1.8+j*0.1, max: 3.3, reason: "근거가 납득 가능합니다." },
        solution: { score: 2.1+j*0.1, max: 3.3, reason: "실행 가능한 방안을 제시했습니다." },
      },
      strengths: "CooperVision 가치를 잘 반영한 답변입니다.",
      improvements: "더 구체적인 실행 단계를 추가하면 더 높은 점수를 받을 수 있습니다.",
      feedback: "전반적으로 훌륭한 답변입니다.",
    }));
    const sample = [
      { team: "드림팀", scores: mk(14), total: mk(14).reduce((a,b)=>a+b.score,0) },
      { team: "스타팀", scores: mk(12), total: mk(12).reduce((a,b)=>a+b.score,0) },
      { team: "챔피언팀", scores: mk(16), total: mk(16).reduce((a,b)=>a+b.score,0) },
    ].sort((a,b) => b.total - a.total);
    try {
      const tp = new Promise((_, r) => setTimeout(() => r(new Error("timeout")), 4000));
      await Promise.race([fetch("/api/teams", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ key: STORAGE_KEY, teams: sample }) }), tp]);
    } catch {}
    setTeams(sample);
    setLastRefresh(new Date().toLocaleTimeString("ko-KR"));
  };

  const viewTeams = zoneFilter !== null
    ? [...teams].filter(t => t.scores?.[zoneFilter]).sort((a,b) => (b.scores[zoneFilter]?.score||0) - (a.scores[zoneFilter]?.score||0))
    : teams;

  const TeamCard = ({ t, rank }) => {
    const open = selectedTeam === t.team;
    const [openZone, setOpenZone] = useState(null);
    const scoresArr = Array.isArray(t.scores) ? t.scores : MISSIONS.map((_, i) => t.scores?.[i]);
    return (
      <div style={{ background: open ? "#1E293B" : "#1A2332", border: `1px solid ${open ? "#4F46E5" : "#334155"}`, borderRadius: 14, marginBottom: 10, overflow: "hidden" }}>
        <div style={{ padding: "14px 18px", cursor: "pointer" }} onClick={() => setSelectedTeam(open ? null : t.team)}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 10 }}>
            <div style={{ width: 30, height: 30, borderRadius: "50%", background: rank === 0 ? "#F59E0B" : rank === 1 ? "#9CA3AF" : rank === 2 ? "#B45309" : "#334155", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, flexShrink: 0 }}>{rank + 1}</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 15 }}>{t.team}</div>
              <div style={{ height: 4, background: "#334155", borderRadius: 2, marginTop: 5 }}><div style={{ height: "100%", width: `${Math.round((t.total / (MISSIONS.length * MAX_SCORE)) * 100)}%`, background: rank === 0 ? "#F59E0B" : "#4F46E5", borderRadius: 2 }} /></div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontFamily: "Georgia, serif", fontSize: 22, fontWeight: 700, color: rank === 0 ? "#F59E0B" : "#fff" }}>{t.total}</div>
              <div style={{ fontSize: 11, color: "#64748B" }}>점</div>
            </div>
            <span style={{ fontSize: 11, color: "#64748B" }}>{open ? "▲" : "▼"}</span>
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            {MISSIONS.map((m, j) => {
              const s = scoresArr[j];
              return (
                <div key={j} style={{ flex: 1, textAlign: "center" }}>
                  <div style={{ height: 22, background: "#0F172A", borderRadius: 4, display: "flex", alignItems: "flex-end", overflow: "hidden", marginBottom: 3 }}>
                    <div style={{ width: "100%", height: s ? `${(s.score/MAX_SCORE)*100}%` : "0%", background: m.color, opacity: s ? 1 : 0.15 }} />
                  </div>
                  <div style={{ fontSize: 9, color: "#64748B" }}>{m.zone}</div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: s ? "#fff" : "#334155" }}>{s ? s.score : "–"}</div>
                </div>
              );
            })}
          </div>
        </div>
        {open && (
          <div style={{ borderTop: "1px solid #334155", padding: "14px 18px" }}>
            {scoresArr.map((s, j) => {
              if (!s) return null;
              const m = MISSIONS[j];
              const zOpen = openZone === j;
              return (
                <div key={j} style={{ marginBottom: 14 }}>
                  <button onClick={() => setOpenZone(zOpen ? null : j)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, background: "transparent", border: "none", cursor: "pointer", padding: "6px 0", borderBottom: "1px solid #334155", marginBottom: 8 }}>
                    <div style={{ width: 22, height: 22, borderRadius: "50%", background: m.color, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, flexShrink: 0 }}>{m.zone}</div>
                    <span style={{ fontSize: 13, fontWeight: 600, color: "#CBD5E1", flex: 1, textAlign: "left" }}>{m.title}</span>
                    <span style={{ fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700, color: m.color }}>{s.score}점</span>
                    <span style={{ fontSize: 10, color: "#64748B" }}>{zOpen ? "▲" : "▼"}</span>
                  </button>
                  {zOpen && (
                    <div>
                      {s.breakdown && (
                        <div style={{ display: "flex", gap: 5, marginBottom: 8 }}>
                          {[{l:"CV가치",k:"cv_value",max:10},{l:"논리",k:"logic",max:3.3},{l:"합리",k:"reason",max:3.3},{l:"해결",k:"solution",max:3.3}].map(item => (
                            <div key={item.k} style={{ flex: 1, background: "#0F172A", borderRadius: 6, padding: "6px 8px", textAlign: "center" }}>
                              <div style={{ fontSize: 9, color: "#64748B", marginBottom: 2 }}>{item.l}</div>
                              <div style={{ fontSize: 12, fontWeight: 700, color: m.color }}>{typeof s.breakdown[item.k] === "number" ? s.breakdown[item.k].toFixed(1) : "–"}</div>
                            </div>
                          ))}
                        </div>
                      )}
                      {s.criteria_feedback && [
                        {key:"cv_value",label:"CooperVision 가치",max:10},
                        {key:"logic",label:"논리성",max:3.3},
                        {key:"reason",label:"합리성",max:3.3},
                        {key:"solution",label:"해결 가능성",max:3.3},
                      ].map(item => {
                        const cf = s.criteria_feedback[item.key];
                        const sc = s.breakdown?.[item.key] ?? cf?.score ?? 0;
                        return (
                          <div key={item.key} style={{ background: "#0F172A", borderRadius: 8, padding: "8px 10px", marginBottom: 6 }}>
                            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                              <span style={{ fontSize: 11, fontWeight: 600, color: "#CBD5E1" }}>{item.label}</span>
                              <span style={{ fontSize: 11, fontWeight: 700, color: m.color }}>{typeof sc === "number" ? sc.toFixed(1) : "–"}/{item.max.toFixed(1)}</span>
                            </div>
                            <div style={{ height: 3, background: "#1E293B", borderRadius: 2, marginBottom: cf?.reason ? 5 : 0 }}><div style={{ height: "100%", width: `${Math.min(100,(sc/item.max)*100)}%`, background: m.color, borderRadius: 2 }} /></div>
                            {cf?.reason && <div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{cf.reason}</div>}
                          </div>
                        );
                      })}
                      {s.strengths && <div style={{ background: "#0F172A", borderRadius: 7, padding: "8px 10px", marginBottom: 5, borderLeft: "3px solid #10B981" }}><div style={{ fontSize: 9, color: "#10B981", fontWeight: 700, marginBottom: 3 }}>잘한 점</div><div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{s.strengths}</div></div>}
                      {s.improvements && <div style={{ background: "#0F172A", borderRadius: 7, padding: "8px 10px", borderLeft: "3px solid #F59E0B" }}><div style={{ fontSize: 9, color: "#F59E0B", fontWeight: 700, marginBottom: 3 }}>개선할 점</div><div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{s.improvements}</div></div>}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={{ minHeight: "100vh", background: "#0F172A", color: "#fff" }}>
      <div style={{ background: "#1E293B", borderBottom: "1px solid #334155", padding: "14px 20px", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <div style={{ flex: 1 }}><div style={{ fontSize: 10, color: "#64748B", letterSpacing: 2, marginBottom: 2 }}>COOPERVISION VALUE WORKSHOP</div><div style={{ fontFamily: "Georgia, serif", fontSize: 17, fontWeight: 700 }}>Control Tower</div></div>
        <div style={{ fontSize: 11, color: "#64748B" }}>갱신 {lastRefresh}</div>
        <button onClick={refresh} style={{ padding: "6px 12px", background: "#334155", border: "none", borderRadius: 8, color: "#CBD5E1", fontSize: 12, cursor: "pointer" }}>새로고침</button>
        <button onClick={seedTestData} style={{ padding: "6px 12px", background: "#1D4ED8", border: "none", borderRadius: 8, color: "#fff", fontSize: 12, cursor: "pointer" }}>테스트 데이터</button>
        {!confirmClear
          ? <button onClick={() => setConfirmClear(true)} style={{ padding: "6px 12px", background: "transparent", border: "1px solid #EF4444", borderRadius: 8, color: "#EF4444", fontSize: 12, cursor: "pointer" }}>초기화</button>
          : <div style={{ display: "flex", gap: 6 }}><button onClick={handleClear} style={{ padding: "6px 12px", background: "#EF4444", border: "none", borderRadius: 8, color: "#fff", fontSize: 12, cursor: "pointer" }}>확인</button><button onClick={() => setConfirmClear(false)} style={{ padding: "6px 12px", background: "#334155", border: "none", borderRadius: 8, color: "#CBD5E1", fontSize: 12, cursor: "pointer" }}>취소</button></div>}
        <button onClick={onExit} style={{ padding: "6px 12px", background: "transparent", border: "1px solid #475569", borderRadius: 8, color: "#94A3B8", fontSize: 12, cursor: "pointer" }}>나가기</button>
      </div>
      <div style={{ padding: "18px 20px" }}>
        {loading && <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, padding: "8px 14px", background: "#1E293B", borderRadius: 8, width: "fit-content" }}><span style={{ ...S.spinner, borderTopColor: "#94A3B8" }} /><span style={{ fontSize: 12, color: "#94A3B8" }}>불러오는 중...</span></div>}
        <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
          <button onClick={() => setZoneFilter(null)} style={{ padding: "6px 14px", borderRadius: 20, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 600, background: zoneFilter === null ? "#fff" : "#1E293B", color: zoneFilter === null ? "#0F172A" : "#64748B" }}>전체 순위</button>
          {MISSIONS.map((m, i) => <button key={i} onClick={() => setZoneFilter(zoneFilter === i ? null : i)} style={{ padding: "6px 14px", borderRadius: 20, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 600, background: zoneFilter === i ? m.color : "#1E293B", color: zoneFilter === i ? "#fff" : "#64748B" }}>{m.zone} — {m.title.replace(" 존","")}</button>)}
        </div>

        {teams.length === 0 && !loading ? (
          <div style={{ textAlign: "center", padding: 60, color: "#64748B" }}>아직 제출한 팀이 없습니다<br /><span style={{ fontSize: 12, marginTop: 8, display: "block" }}>테스트 데이터 버튼으로 샘플을 추가할 수 있어요</span></div>
        ) : zoneFilter === null ? (
          <div>
            <div style={{ fontSize: 12, color: "#64748B", marginBottom: 12 }}>{teams.length}개 팀 · 팀 클릭 → 존 클릭 → 항목별 채점 근거</div>
            {viewTeams.map((t, i) => <TeamCard key={t.team} t={t} rank={i} />)}
          </div>
        ) : (
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
              <div style={{ width: 36, height: 36, borderRadius: "50%", background: MISSIONS[zoneFilter].color, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700 }}>{MISSIONS[zoneFilter].zone}</div>
              <div><div style={{ fontFamily: "Georgia, serif", fontSize: 17, fontWeight: 700 }}>{MISSIONS[zoneFilter].title}</div><div style={{ fontSize: 12, color: "#64748B" }}>{viewTeams.length}개 팀 비교</div></div>
            </div>
            {viewTeams.map((t, i) => {
              const scoresArr = Array.isArray(t.scores) ? t.scores : MISSIONS.map((_, j) => t.scores?.[j]);
              const s = scoresArr[zoneFilter];
              const m = MISSIONS[zoneFilter];
              if (!s) return null;
              return (
                <div key={t.team} style={{ background: "#1A2332", border: "1px solid #334155", borderRadius: 14, padding: "16px 18px", marginBottom: 12 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
                    <div style={{ width: 28, height: 28, borderRadius: "50%", background: i === 0 ? "#F59E0B" : "#334155", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700 }}>{i + 1}</div>
                    <span style={{ fontSize: 15, fontWeight: 700, flex: 1 }}>{t.team}</span>
                    <span style={{ fontFamily: "Georgia, serif", fontSize: 22, fontWeight: 700, color: m.color }}>{s.score}점</span>
                  </div>
                  {s.criteria_feedback && [
                    {key:"cv_value",label:"CooperVision 가치",max:10},
                    {key:"logic",label:"논리성",max:3.3},
                    {key:"reason",label:"합리성",max:3.3},
                    {key:"solution",label:"해결 가능성",max:3.3},
                  ].map(item => {
                    const cf = s.criteria_feedback[item.key];
                    const sc = s.breakdown?.[item.key] ?? cf?.score ?? 0;
                    return (
                      <div key={item.key} style={{ background: "#0F172A", borderRadius: 8, padding: "8px 10px", marginBottom: 6 }}>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                          <span style={{ fontSize: 11, fontWeight: 600, color: "#CBD5E1" }}>{item.label}</span>
                          <span style={{ fontSize: 11, fontWeight: 700, color: m.color }}>{typeof sc === "number" ? sc.toFixed(1) : "–"}/{item.max.toFixed(1)}</span>
                        </div>
                        <div style={{ height: 3, background: "#1E293B", borderRadius: 2, marginBottom: cf?.reason ? 5 : 0 }}><div style={{ height: "100%", width: `${Math.min(100,(sc/item.max)*100)}%`, background: m.color, borderRadius: 2 }} /></div>
                        {cf?.reason && <div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{cf.reason}</div>}
                      </div>
                    );
                  })}
                  {s.strengths && <div style={{ background: "#0F172A", borderRadius: 8, padding: "8px 10px", marginBottom: 5, marginTop: 5, borderLeft: "3px solid #10B981" }}><div style={{ fontSize: 9, color: "#10B981", fontWeight: 700, marginBottom: 3 }}>잘한 점</div><div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{s.strengths}</div></div>}
                  {s.improvements && <div style={{ background: "#0F172A", borderRadius: 8, padding: "8px 10px", borderLeft: "3px solid #F59E0B" }}><div style={{ fontSize: 9, color: "#F59E0B", fontWeight: 700, marginBottom: 3 }}>개선할 점</div><div style={{ fontSize: 11, color: "#94A3B8", lineHeight: 1.6 }}>{s.improvements}</div></div>}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

// ── 메인 앱 ───────────────────────────────────────────────────
export default function App() {
  const [view, setView] = useState("login");        // login | zone-select | game | final | tower
  const [teamName, setTeamName] = useState("");
  const [selectedZones, setSelectedZones] = useState(MISSIONS.map((_, i) => i));
  const [missionIndex, setMissionIndex] = useState(0);
  const [scores, setScores] = useState({});         // { zoneIndex: result }

  const handleLogin = (name) => { setTeamName(name); setView("zone-select"); };

  const handleZoneStart = (zones) => {
    setSelectedZones(zones);
    setMissionIndex(zones[0]);
    setScores({});
    setView("game");
  };

  const handleNext = (zoneIdx, result) => {
    const newScores = { ...scores, [zoneIdx]: result };
    setScores(newScores);
    const pos = selectedZones.indexOf(zoneIdx);
    if (pos < selectedZones.length - 1) {
      setMissionIndex(selectedZones[pos + 1]);
    } else {
      const scoreArr = selectedZones.map(i => newScores[i]).filter(Boolean);
      upsertTeam({ team: teamName, scores: newScores, total: scoreArr.reduce((a, b) => a + b.score, 0) }).catch(() => {});
      setView("final");
    }
  };

  const handleNavigate = (idx) => { setMissionIndex(idx); };

  const handleRestart = () => { setTeamName(""); setSelectedZones(MISSIONS.map((_, i) => i)); setMissionIndex(0); setScores({}); setView("login"); };

  const handleGoTower = () => setView("tower");

  return (
    <>
      <style>{`* { box-sizing: border-box; margin: 0; padding: 0; } body { background: #F3F4F6; font-family: -apple-system, 'Helvetica Neue', sans-serif; } input:focus, textarea:focus { outline: none; } @keyframes spin { to { transform: rotate(360deg); } } @keyframes fadeUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }`}</style>
      {view === "login"       && <LoginScreen onLogin={handleLogin} onInstructor={() => setView("tower")} />}
      {view === "zone-select" && <ZoneSelectScreen teamName={teamName} onStart={handleZoneStart} onBack={() => setView("login")} />}
      {view === "game"        && <MissionScreen key={`m-${missionIndex}`} teamName={teamName} missionIndex={missionIndex} selectedZones={selectedZones} scores={scores} onNext={handleNext} onGoTower={handleGoTower} onNavigate={handleNavigate} />}
      {view === "final"       && <FinalScreen teamName={teamName} selectedZones={selectedZones} scores={scores} onRestart={handleRestart} onGoTower={handleGoTower} />}
      {view === "tower"       && <ControlTower onExit={() => setView("login")} />}
    </>
  );
}

const S = {
  screen:   { minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", padding: "24px 16px", background: "#F3F4F6" },
  card:     { width: "100%", maxWidth: 500, background: "#fff", borderRadius: 20, padding: "28px 24px", boxShadow: "0 4px 40px rgba(0,0,0,0.08)", animation: "fadeUp 0.4s ease" },
  label:    { display: "block", fontSize: 13, fontWeight: 600, color: "#374151", marginBottom: 8 },
  input:    { width: "100%", padding: "12px 16px", fontSize: 16, border: "1.5px solid #E5E7EB", borderRadius: 10, fontFamily: "inherit", color: "#111", marginBottom: 16 },
  textarea: { width: "100%", padding: "14px 16px", fontSize: 15, border: "1.5px solid #E5E7EB", borderRadius: 10, fontFamily: "inherit", color: "#111", resize: "vertical", lineHeight: 1.6, marginBottom: 8, transition: "border-color 0.2s" },
  btn:      { display: "block", width: "100%", padding: "14px", fontSize: 15, fontWeight: 700, color: "#fff", background: "#1E1B4B", border: "none", borderRadius: 12, cursor: "pointer", fontFamily: "inherit", boxShadow: "0 4px 20px rgba(30,27,75,0.2)" },
  spinner:  { display: "inline-block", width: 14, height: 14, border: "2px solid rgba(0,0,0,0.1)", borderTopColor: "currentColor", borderRadius: "50%", animation: "spin 0.7s linear infinite" },
};
